"""Terrain clear, initial fill, row/column streaming and search contracts."""
import hashlib,json
from pathlib import Path
from inventory_rom import ROM_HASH
from m68k_static import Decoder
p=Path(__file__).resolve().parents[1];root=p.parents[1];rom=(p/'local/rolo.md').read_bytes();assert hashlib.sha256(rom).hexdigest()==ROM_HASH
rp=root/'work/terrain-stream-batch-results.json';r=json.loads(rp.read_text(encoding='utf-8-sig'));assert r==dict(passed=True,**{x:4096 for x in ['4158','417A','42BC','42E4','4096','4270','422C','4030','4020']})
sources=['src/core/terrain_streaming.hpp','src/core/terrain_stream_rows.hpp','src/core/terrain_record_search.hpp','src/core/terrain_camera_world.hpp','src/core/terrain_descriptor.hpp','src/core/terrain_macro_copy.hpp','src/core/actor_state.hpp','tests/terrain_stream_batch_verification_tests.cpp'];exe=root/'work/terrain_stream_batch_verification_tests.exe';assert exe.stat().st_mtime>=max((p/s).stat().st_mtime for s in sources)
inv=json.loads((p/'docs/stage9/inventory.json').read_text(encoding='utf-8'));accepted={a for x in inv['routines'] for a in x['blocks']};records=[]
specs=[(0x4020,[(0x4020,0x4030),(0x403c,0x4096)],'Clear exactly16384 backing bytes; retain all adjacent bytes. Native foreground camera clear adapter.'),(0x4030,[(0x4030,0x4096)],'Clear exactly8192 backing bytes; retain adjacent bytes. Native background camera clear adapter.'),(0x4096,[(0x4096,0x4158)],'Initial row budget plane4-7 predecrements, negative initial rows retry without another budget. Ring cursor advances and masks; read MAP row offsets before nonempty height gate. Forward window width400; initial descriptor clipping/dispatch delegated.'),(0x4158,[(0x4158,0x417a),(0x41a8,0x4270)],'Top row index y/16*2-16: negative return before clears. Otherwise clear128bytes in each plane separation, even above height; clamp left edge and window310; reverse record visitation, OnlyEmpty copy.'),(0x417a,[(0x417a,0x422c),(0x4270,0x42bc)],'Bottom row y/16*2+plane6*2+28; ring offset and delayed clear row+380; two128byte clears before height/MAP admission. Forward window310, Replace dispatch.'),(0x422c,[(0x422c,0x4270)],'Backward binary seed then reverse window traversal, left inclusive/right exclusive, read-before-lower-bound semantics with guard word admission; visitor preserves reverse copy order.'),(0x4270,[(0x4270,0x42bc)],'Forward binary seed then ascending window traversal, left inclusive/right exclusive on admitted nonwrapping windows; visitor observes original record offsets/order.'),(0x42bc,[(0x42bc,0x42e4),(0x430c,0x442a)],'Left target=(X-160)&FFF0, column=(target/8)&7E. DBF clear32words per plane4/16 block. Subsequent row-budget predecrement; negative rows consume budget; nonempty height gate then exact-X record and OrderedMetadata dispatch.'),(0x42e4,[(0x42e4,0x442a)],'Right target=(X&FFF0)+1A0 with clear column using target+F0. Same original clear, budget, MAP reads, exact search and OrderedMetadata continuation as left.')]
for start,ranges,contract in specs:
 items=[]
 for lo,hi in ranges:
  at=lo
  while at<hi:
   assert at in accepted,(hex(start),hex(at));i=Decoder(rom,at).decode();items.append(i);at+=i['size']
  assert at==hi
 records.append(dict(address=start,hex=f'{start:06X}',end_exclusive=max(hi for lo,hi in ranges),code_ranges=ranges,original_bytes=rom[start:max(hi for lo,hi in ranges)].hex(),instruction_evidence=items,verification_status='verified',status='verified green: local terrain stream',native_sources=sources[:4],checked_cases=4096,contract=contract,proof='Independent linear sorted-record specification and byte clear/row-budget model; 4096 fixtures each with0..32 unique records per row, empty/nonempty height boundaries, X/Y edge positions, two ring masks, foreground/background lengths and metadata. Compare complete16384byte backing and ordered descriptor service trace/count. Separate direct forward/backward/exact searches compare record offsets against linear order. Already green descriptor/macro child contracts reused only for copy semantics.',scope='Local valid nonnegative signed MAP offsets, strictly increasing unique X per row, nonwrapping windows and admitted backing/row extents; immutable plane/map during service calls. Counts32/64 avoid zero-shift DBF65536 clear extent. Duplicate-X/binary equality outside right/window-wrap and arbitrary malformed MAP admission remain external. Special descriptors are explicit ordered service handoffs; full actor spawning/VDP hardware not claimed.'))
report=dict(rom_sha256=ROM_HASH,source_sha256={s:hashlib.sha256((p/s).read_bytes()).hexdigest() for s in sources},records=records,test_executable_sha256=hashlib.sha256(exe.read_bytes()).hexdigest(),results_sha256=hashlib.sha256(rp.read_bytes()).hexdigest())
(p/'docs/stage9/terrain-stream-batch-verification.json').write_text(json.dumps(report,indent=2)+'\n',encoding='utf-8');print('Nine terrain streaming contracts verified.')
